t.script:
(function() {
'use strict';

/* ========================================================
   DATA from server
   ======================================================== */
const TEMPLATE_ID = ;
const SIGN_ITEM_TYPES = ;
const SIGN_ROLES = ;
const INITIAL_ITEMS = ;
const TEMPLATE_NAME = ;

/* ========================================================
   STATE
   ======================================================== */
let signItems = [];   // { _id, id, type_id, type, page, posX, posY, width, height, required, responsible_id, name, placeholder, _dirty }
let nextLocalId = -1; // negative IDs = newly created (not yet saved)
let selectedItemId = null;
let isDirty = false;
let isEditMode = false;

function setEditMode(mode) {
    isEditMode = mode;
    updateEditModeUI();
}

function updateEditModeUI() {
    const btnSave = document.getElementById('es-btn-save');
    const btnDiscard = document.getElementById('es-btn-discard');
    const btnEdit = document.getElementById('es-btn-edit');
    const status = document.getElementById('es-save-status');
    const btnSend = document.getElementById('es-btn-send');

    if (isEditMode) {
        if (btnSave) btnSave.style.display = '';
        if (btnDiscard) btnDiscard.style.display = '';
        if (btnEdit) btnEdit.style.display = 'none';
        if (status) status.style.display = '';
        if (btnSend) btnSend.disabled = true;
    } else {
        if (btnSave) btnSave.style.display = 'none';
        if (btnDiscard) btnDiscard.style.display = 'none';
        if (btnEdit) btnEdit.style.display = '';
        if (status) status.style.display = 'none';
        if (btnSend) btnSend.disabled = false;
    }

    const btnAddSigner = document.querySelector('.es-btn-add-signer');
    if (btnAddSigner) {
        btnAddSigner.style.display = isEditMode ? '' : 'none';
    }

    const list = document.getElementById('es-signers-list');
    if (list) {
        const rows = list.querySelectorAll('.es-signer-row');
        rows.forEach(row => {
            const idx = row.id.replace('signer-row-', '');

            const nameEl = document.getElementById('signer-name-' + idx);
            const emailEl = document.getElementById('signer-email-' + idx);
            const roleEl = document.getElementById('signer-role-' + idx);

            if (nameEl) nameEl.disabled = !isEditMode;
            if (emailEl) emailEl.disabled = !isEditMode;
            if (roleEl) roleEl.disabled = !isEditMode;

            const btnRemove = row.querySelector('.es-signer-remove');
            if (btnRemove) {
                btnRemove.style.display = isEditMode ? '' : 'none';
            }

            const dragHint = row.querySelector('.es-drag-hint');
            if (dragHint) {
                dragHint.style.display = isEditMode ? '' : 'none';
            }

            const fieldCards = row.querySelectorAll('.es-signer-field-card');
            fieldCards.forEach(card => {
                if (isEditMode) {
                    card.setAttribute('draggable', 'true');
                    card.style.opacity = '1';
                    card.style.pointerEvents = 'auto';
                    card.style.cursor = 'grab';
                } else {
                    card.setAttribute('draggable', 'false');
                    card.style.opacity = '0.35';
                    card.style.pointerEvents = 'none';
                    card.style.cursor = 'default';
                }
            });
        });
    }

    const fieldOverlays = document.querySelectorAll('.sign-field-item');
    fieldOverlays.forEach(el => {
        if (isEditMode) {
            el.style.pointerEvents = 'auto';
            el.style.cursor = 'move';

            const resizeHandle = el.querySelector('.sign-field-resize');
            if (resizeHandle) resizeHandle.style.display = '';

            const deleteBtn = el.querySelector('.sign-field-delete');
            if (deleteBtn) deleteBtn.style.display = '';
        } else {
            el.style.pointerEvents = 'none';
            el.style.cursor = 'default';

            const resizeHandle = el.querySelector('.sign-field-resize');
            if (resizeHandle) resizeHandle.style.display = 'none';

            const deleteBtn = el.querySelector('.sign-field-delete');
            if (deleteBtn) deleteBtn.style.display = 'none';
        }
    });

    deselectAll();
}

// PDF state
let pdfDoc = null;
let pageWrappers = {}; // pageNum → { wrapper, canvas, viewport }

/* ========================================================
   INIT PDF.js
   ======================================================== */
const pdfjsLib = window.pdfjsLib || window['pdfjs-dist/build/pdf'];
try {
    const worker = new Worker('/web/static/lib/pdfjs/build/pdf.worker.js', { type: 'module' });
    pdfjsLib.GlobalWorkerOptions.workerPort = worker;
} catch (e) {
    console.warn("Could not start module worker, falling back to fake worker:", e);
}

/* ========================================================
   TYPE/ROLE HELPERS
   ======================================================== */
const TYPE_META = {
    signature: { label: 'Signature', icon: '✍', desc: 'Handwritten signature',    cls: 'sfi-signature', ftCls: 'ft-signature', defW: 0.2, defH: 0.07 },
    initial:   { label: 'Initial',   icon: '📝', desc: 'Initials abbreviation',    cls: 'sfi-initial',   ftCls: 'ft-initial',   defW: 0.1, defH: 0.05 },
    text:      { label: 'Text',      icon: '𝐓',  desc: 'Single-line text input',  cls: 'sfi-text',      ftCls: 'ft-text',      defW: 0.2, defH: 0.04 },
    textarea:  { label: 'Text Area', icon: '≡',  desc: 'Multi-line text input',   cls: 'sfi-textarea',  ftCls: 'ft-textarea',  defW: 0.25, defH: 0.1 },
    checkbox:  { label: 'Checkbox',  icon: '☑',  desc: 'Checkbox / tick field',   cls: 'sfi-checkbox',  ftCls: 'ft-checkbox',  defW: 0.05, defH: 0.05 },
};

function getTypeMeta(typeStr) {
    return TYPE_META[typeStr] || TYPE_META['text'];
}

function getRoleById(id) {
    return SIGN_ROLES.find(r => r.id === id) || null;
}

function getOdooColorHex(colorIdx) {
    const palette = [
        '#e74c3c','#e67e22','#f1c40f','#2ecc71','#1abc9c',
        '#3498db','#9b59b6','#e91e63','#795548','#607d8b',
        '#00bcd4','#cddc39'
    ];
    return palette[colorIdx % palette.length] || '#6366f1';
}

// buildFieldCards and buildRoleSelect removed in favor of per-signer fields and dynamic signer selector in props panel.

/* ========================================================
   SIDEBAR DRAG START
   ======================================================== */
let dragPayload = null; // { typeId, itemType, typeName, signerIdx, signerColor }

function onSidebarDragStart(e) {
    const card = e.currentTarget;
    const signerIdx   = card.dataset.signerIdx   ? parseInt(card.dataset.signerIdx, 10)   : null;
    const signerColor = card.dataset.signerColor  || null;
    dragPayload = {
        typeId: parseInt(card.dataset.typeId),
        itemType: card.dataset.itemType,
        typeName: card.dataset.typeName,
        signerIdx:   signerIdx,
        signerColor: signerColor,
        defName: card.dataset.defName || '',
        defPlaceholder: card.dataset.defPlaceholder || '',
    };
    card.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'copy';
    e.dataTransfer.setData('text/plain', 'es-field');
}

/* ========================================================
   PAGE WRAPPER DROP HANDLERS
   ======================================================= */
function attachPageDropHandlers(wrapper, pageNum) {
    wrapper.addEventListener('dragover', e => {
        if (!dragPayload) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
        wrapper.classList.add('drag-over');
    });
    wrapper.addEventListener('dragleave', e => {
        if (!e.relatedTarget || !wrapper.contains(e.relatedTarget)) {
            wrapper.classList.remove('drag-over');
        }
    });
    wrapper.addEventListener('drop', e => {
        e.preventDefault();
        wrapper.classList.remove('drag-over');
        if (!dragPayload) return;

        const { typeId, itemType, typeName, signerIdx, signerColor, defName, defPlaceholder } = dragPayload;
        dragPayload = null;

        const rect = wrapper.getBoundingClientRect();
        const meta = getTypeMeta(itemType);
        const defW = meta.defW;
        const defH = meta.defH;

        // Centre the dropped item on the cursor
        let posX = (e.clientX - rect.left) / rect.width  - defW / 2;
        let posY = (e.clientY - rect.top)  / rect.height - defH / 2;
        posX = Math.max(0, Math.min(1 - defW, posX));
        posY = Math.max(0, Math.min(1 - defH, posY));

        let signerRoleId = false;
        if (signerIdx) {
            const roleEl = document.getElementById('signer-role-' + signerIdx);
            if (roleEl && roleEl.value) {
                signerRoleId = parseInt(roleEl.value, 10);
            }
        }

        let isReq = true;
        const typeDef = SIGN_ITEM_TYPES.find(t => t.id === typeId);
        if (typeDef) {
            isReq = typeDef.is_mandatory ? true : false;
        }

        const item = {
            _id: nextLocalId--,
            id: 0,
            type_id: [typeId, typeName],
            type: itemType,
            page: pageNum,
            posX: +posX.toFixed(4),
            posY: +posY.toFixed(4),
            width: defW,
            height: defH,
            required: isReq,
            responsible_id: signerRoleId,
            name: defName || '',
            placeholder: defPlaceholder || '',
            _signerIdx:   signerIdx   || null,
            _signerColor: signerColor || null,
        };
        signItems.push(item);
        placeFieldOnPage(item);
        selectItem(item._id);
        markDirty();
        updateSignerFieldCounts();
    });
}

/* ========================================================
   RENDER PDF & PLACE EXISTING ITEMS
   ======================================================== */
async function renderPDF(url) {
    try {
        const loadingTask = pdfjsLib.getDocument(url);
        pdfDoc = await loadingTask.promise;

        const viewer = document.getElementById('es-viewer');
        const loadingEl = document.getElementById('es-loading');
        if (loadingEl) loadingEl.remove();

        for (let i = 1; i <= pdfDoc.numPages; i++) {
            const page = await pdfDoc.getPage(i);
            const scale = 1.8;
            const viewport = page.getViewport({ scale });

            // Page label
            const labelEl = document.createElement('div');
            labelEl.className = 'es-page-label';
            labelEl.textContent = `Page ${i} of ${pdfDoc.numPages}`;

            // Wrapper
            const wrapper = document.createElement('div');
            wrapper.className = 'es-page-wrapper';
            wrapper.dataset.page = i;
            wrapper.style.position = 'relative';
            wrapper.style.maxWidth = '900px';
            wrapper.style.width = '100%';

            // Canvas
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            canvas.height = viewport.height;
            canvas.width  = viewport.width;
            canvas.style.display = 'block';
            canvas.style.width = '100%';

            wrapper.appendChild(canvas);
            viewer.appendChild(wrapper);
            viewer.appendChild(labelEl);

            const renderCtx = { canvasContext: ctx, viewport };
            await page.render(renderCtx).promise;

            pageWrappers[i] = { wrapper, canvas, viewport };
            attachPageDropHandlers(wrapper, i);

            // Empty hint
            const hint = document.createElement('div');
            hint.className = 'es-empty-hint';
            hint.id = `page-hint-${i}`;
            hint.innerHTML = `<div class="es-empty-hint-icon">&#8681;</div><div class="es-empty-hint-text">Drag a field here</div>`;
            wrapper.appendChild(hint);
        }

        // Place existing items
        signItems.forEach(item => placeFieldOnPage(item));
    } catch (err) {
        console.error("Error loading PDF:", err);
        const loadingText = document.querySelector('.es-loading-text');
        if (loadingText) {
            loadingText.style.color = '#ef4444';
            loadingText.textContent = 'Error loading PDF: ' + err.message;
        }
        const spinner = document.querySelector('.es-spinner');
        if (spinner) {
            spinner.style.borderTopColor = '#ef4444';
            spinner.style.animationPlayState = 'paused';
        }
    }
}

/* ========================================================
   PLACE A FIELD OVERLAY ON ITS PAGE
   ======================================================== */
function placeFieldOnPage(item) {
    const pw = pageWrappers[item.page];
    if (!pw) return;

    // Hide empty hint if fields exist on this page
    const hint = document.getElementById(`page-hint-${item.page}`);
    if (hint) hint.style.display = 'none';

    const meta = getTypeMeta(item.type);

    const el = document.createElement('div');
    el.className = `sign-field-item ${meta.cls}`;
    el.id = `sfi-${item._id}`;
    el.style.left   = (item.posX * 100) + '%';
    el.style.top    = (item.posY * 100) + '%';
    el.style.width  = (item.width * 100) + '%';
    el.style.height = (item.height * 100) + '%';

    // Apply signer color (from drag) or role color (for existing items)
    applyRoleColorToEl(el, item.responsible_id, item._signerColor || null);

    // Badge
    const badge = document.createElement('div');
    badge.className = 'sign-field-badge';
    badge.textContent = meta.label;
    el.appendChild(badge);

    // Label
    const lbl = document.createElement('div');
    lbl.className = 'sign-field-label';
    lbl.textContent = item.name || meta.icon;
    el.appendChild(lbl);

    // Delete button
    const delBtn = document.createElement('button');
    delBtn.className = 'sign-field-delete';
    delBtn.innerHTML = '&#10005;';
    delBtn.title = 'Delete field';
    delBtn.addEventListener('mousedown', e => { e.stopPropagation(); deleteItem(item._id); });
    el.appendChild(delBtn);

    // Resize handle
    const resizeHandle = document.createElement('div');
    resizeHandle.className = 'sign-field-resize';
    resizeHandle.title = 'Resize';
    resizeHandle.addEventListener('mousedown', e => onResizeStart(e, item._id));
    el.appendChild(resizeHandle);

    // Click → select
    el.addEventListener('mousedown', e => {
        if (e.target === delBtn || e.target === resizeHandle) return;
        onFieldMouseDown(e, item._id);
    });

    pw.wrapper.appendChild(el);
    if (typeof updateSignerFieldCounts === 'function') {
        updateSignerFieldCounts();
    }
}

/* ========================================================
   APPLY SIGNER / ROLE COLOR
   ======================================================== */
function applyRoleColorToEl(el, roleId, signerColor) {
    const hex = signerColor || (function() {
        if (!roleId) return null;
        const roleIdNum = Array.isArray(roleId) ? roleId[0] : roleId;
        const role = getRoleById(roleIdNum);
        if (!role) return null;
        return getOdooColorHex(role.color || 0);
    }()) || '#6366f1';

    el.style.borderColor = hex;
    el.style.background = hex + '22';
    el.style.color = hex;
}

/* ========================================================
   DRAG TO MOVE
   ======================================================== */
let movingItemId = null;
let movingStartX, movingStartY;
let movingItemOrigX, movingItemOrigY;
let movingWrapper = null;

function onFieldMouseDown(e, itemId) {
    e.preventDefault();
    selectItem(itemId);

    movingItemId = itemId;
    movingStartX = e.clientX;
    movingStartY = e.clientY;
    const item = signItems.find(it => it._id === itemId);
    movingItemOrigX = item.posX;
    movingItemOrigY = item.posY;
    movingWrapper = pageWrappers[item.page].wrapper;
}

document.addEventListener('mousemove', e => {
    if (movingItemId === null) return;
    const rect = movingWrapper.getBoundingClientRect();
    const item = signItems.find(it => it._id === movingItemId);
    const dx = (e.clientX - movingStartX) / rect.width;
    const dy = (e.clientY - movingStartY) / rect.height;
    item.posX = Math.max(0, Math.min(1 - item.width,  movingItemOrigX + dx));
    item.posY = Math.max(0, Math.min(1 - item.height, movingItemOrigY + dy));
    item.posX = +item.posX.toFixed(4);
    item.posY = +item.posY.toFixed(4);
    const el = document.getElementById(`sfi-${movingItemId}`);
    if (el) {
        el.style.left = (item.posX * 100) + '%';
        el.style.top  = (item.posY * 100) + '%';
    }
    updatePosInfo(item);
    markDirty();
});

document.addEventListener('mouseup', () => {
    if (movingItemId !== null) {
        movingItemId = null;
        movingWrapper = null;
    }
});

/* ========================================================
   RESIZE
   ======================================================== */
let resizingItemId = null;
let resizingStartX, resizingStartY;
let resizingOrigW, resizingOrigH;
let resizingWrapper = null;

function onResizeStart(e, itemId) {
    e.preventDefault();
    e.stopPropagation();
    resizingItemId = itemId;
    resizingStartX = e.clientX;
    resizingStartY = e.clientY;
    const item = signItems.find(it => it._id === itemId);
    resizingOrigW = item.width;
    resizingOrigH = item.height;
    resizingWrapper = pageWrappers[item.page].wrapper;
}

document.addEventListener('mousemove', e => {
    if (resizingItemId === null) return;
    const rect = resizingWrapper.getBoundingClientRect();
    const item = signItems.find(it => it._id === resizingItemId);
    const dw = (e.clientX - resizingStartX) / rect.width;
    const dh = (e.clientY - resizingStartY) / rect.height;
    item.width  = Math.max(0.02, Math.min(1 - item.posX, resizingOrigW + dw));
    item.height = Math.max(0.01, Math.min(1 - item.posY, resizingOrigH + dh));
    item.width  = +item.width.toFixed(4);
    item.height = +item.height.toFixed(4);
    const el = document.getElementById(`sfi-${resizingItemId}`);
    if (el) {
        el.style.width  = (item.width  * 100) + '%';
        el.style.height = (item.height * 100) + '%';
    }
    updatePosInfo(item);
    markDirty();
});

document.addEventListener('mouseup', () => {
    if (resizingItemId !== null) {
        resizingItemId = null;
        resizingWrapper = null;
    }
});

/* ========================================================
   KEYBOARD DELETE
   ======================================================== */
document.addEventListener('keydown', e => {
    if ((e.key === 'Delete' || e.key === 'Backspace') &&
        selectedItemId !== null &&
        !['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) {
        deleteItem(selectedItemId);
    }
    if (e.key === 'Escape') {
        deselectAll();
    }
});

/* ========================================================
   SELECT / DESELECT
   ======================================================== */
function selectItem(itemId) {
    // Deselect previous
    if (selectedItemId !== null) {
        const prev = document.getElementById(`sfi-${selectedItemId}`);
        if (prev) prev.classList.remove('selected');
    }
    selectedItemId = itemId;
    const el = document.getElementById(`sfi-${itemId}`);
    if (el) el.classList.add('selected');

    // Show properties panel
    const item = signItems.find(it => it._id === itemId);
    if (item) showPropsPanel(item);
}

function deselectAll() {
    if (selectedItemId !== null) {
        const prev = document.getElementById(`sfi-${selectedItemId}`);
        if (prev) prev.classList.remove('selected');
        selectedItemId = null;
    }
    hidePropsPanel();
}

// Click on viewer background → deselect
document.getElementById('es-viewer').addEventListener('mousedown', e => {
    if (e.target === document.getElementById('es-viewer') ||
        e.target.classList.contains('es-page-wrapper') ||
        e.target.tagName === 'CANVAS') {
        deselectAll();
    }
});

/* ========================================================
   PROPERTIES PANEL
   ======================================================== */
function updatePropSignerSelect(selectedSignerIdx) {
    const sel = document.getElementById('es-prop-signer');
    if (!sel) return;
    sel.innerHTML = '<option value="">— No signer —</option>';

    const list = document.getElementById('es-signers-list');
    if (!list) return;
    const rows = list.querySelectorAll('.es-signer-row');
    rows.forEach(row => {
        const idx = parseInt(row.id.replace('signer-row-', ''), 10);
        const nameEl = document.getElementById('signer-name-' + idx);
        const emailEl = document.getElementById('signer-email-' + idx);
        const roleEl = document.getElementById('signer-role-' + idx);

        let signerLabel = 'Signer ' + idx;
        if (nameEl && nameEl.value.trim()) {
            signerLabel += ' (' + nameEl.value.trim() + ')';
        } else if (emailEl && emailEl.value.trim()) {
            signerLabel += ' (' + emailEl.value.trim() + ')';
        } else if (roleEl && roleEl.value) {
            const role = getRoleById(parseInt(roleEl.value, 10));
            if (role) signerLabel += ' (' + role.name + ')';
        }

        const opt = document.createElement('option');
        opt.value = idx;
        opt.textContent = signerLabel;
        if (idx === selectedSignerIdx) {
            opt.selected = true;
        }
        sel.appendChild(opt);
    });
}

function showPropsPanel(item) {
    const meta = getTypeMeta(item.type);
    document.getElementById('es-props-title').textContent = meta.label + ' Field';
    document.getElementById('es-prop-name').value = item.name || '';
    document.getElementById('es-prop-placeholder').value = item.placeholder || '';
    document.getElementById('es-prop-required').checked = item.required !== false;

    // Dynamically populate signer selection
    updatePropSignerSelect(item._signerIdx);

    updatePosInfo(item);

    document.getElementById('es-field-palette').style.display = 'none';
    document.getElementById('es-props-panel').classList.add('visible');
}

function hidePropsPanel() {
    document.getElementById('es-props-panel').classList.remove('visible');
    document.getElementById('es-field-palette').style.display = '';
}

function updatePosInfo(item) {
    document.getElementById('pi-x').textContent = (item.posX * 100).toFixed(1) + '%';
    document.getElementById('pi-y').textContent = (item.posY * 100).toFixed(1) + '%';
    document.getElementById('pi-w').textContent = (item.width  * 100).toFixed(1) + '%';
    document.getElementById('pi-h').textContent = (item.height * 100).toFixed(1) + '%';
}

// Properties changes → update item
function syncPropsToItem() {
    if (selectedItemId === null) return;
    const item = signItems.find(it => it._id === selectedItemId);
    if (!item) return;
    item.name = document.getElementById('es-prop-name').value;
    item.placeholder = document.getElementById('es-prop-placeholder').value;
    item.required = document.getElementById('es-prop-required').checked;

    // Sync signer selection
    const signerVal = document.getElementById('es-prop-signer').value;
    if (signerVal) {
        const signerIdx = parseInt(signerVal, 10);
        item._signerIdx = signerIdx;
        item._signerColor = getSignerColor(signerIdx);

        // Find the signer's role
        const roleEl = document.getElementById('signer-role-' + signerIdx);
        item.responsible_id = (roleEl && roleEl.value) ? parseInt(roleEl.value, 10) : false;
    } else {
        item._signerIdx = null;
        item._signerColor = null;
        item.responsible_id = false;
    }

    // Update the overlay label
    const el = document.getElementById(`sfi-${selectedItemId}`);
    if (el) {
        const lbl = el.querySelector('.sign-field-label');
        if (lbl) lbl.textContent = item.name || getTypeMeta(item.type).icon;
        // Update styling
        applyRoleColorToEl(el, item.responsible_id, item._signerColor || null);
    }
    markDirty();
    updateSignerFieldCounts();
}

document.getElementById('es-prop-name').addEventListener('input', syncPropsToItem);
document.getElementById('es-prop-placeholder').addEventListener('input', syncPropsToItem);
document.getElementById('es-prop-required').addEventListener('change', syncPropsToItem);
document.getElementById('es-prop-signer').addEventListener('change', syncPropsToItem);

document.getElementById('es-props-close').addEventListener('click', deselectAll);

document.getElementById('es-props-delete').addEventListener('click', () => {
    if (selectedItemId !== null) deleteItem(selectedItemId);
});

/* ========================================================
   DELETE ITEM
   ======================================================== */
function deleteItem(itemId) {
    // Remove DOM element
    const el = document.getElementById(`sfi-${itemId}`);
    if (el) el.remove();

    // Remove from state
    const idx = signItems.findIndex(it => it._id === itemId);
    if (idx !== -1) signItems.splice(idx, 1);

    if (selectedItemId === itemId) {
        selectedItemId = null;
        hidePropsPanel();
    }

    // Show empty hint if no more fields on that page
    Object.keys(pageWrappers).forEach(pg => {
        const pgNum = parseInt(pg);
        const hasFields = signItems.some(it => it.page === pgNum);
        const hint = document.getElementById(`page-hint-${pgNum}`);
        if (hint) hint.style.display = hasFields ? 'none' : '';
    });

    markDirty();
    updateSignerFieldCounts();
}



/* ========================================================
   DIRTY / STATUS
   ======================================================== */
function markDirty() {
    isDirty = true;
    const status = document.getElementById('es-save-status');
    if (status) {
        status.style.color = '#fbbf24';
        status.title = 'Unsaved changes';
        status.innerHTML = '&#9729;&#65039;&#9679;';
    }
    const txt = document.getElementById('es-save-text');
    if (txt) txt.textContent = 'Unsaved changes';
}

function markSaved() {
    isDirty = false;
    const status = document.getElementById('es-save-status');
    if (status) {
        status.style.color = '#10b981';
        status.title = 'All changes saved';
        status.innerHTML = '&#9729;&#65039;&#10003;';
    }
    const txt = document.getElementById('es-save-text');
    if (txt) txt.textContent = 'All changes saved';
}

/* ========================================================
   SAVE
   ======================================================== */
async function saveTemplate() {
    const btn = document.getElementById('es-btn-save');
    btn.disabled = true;
    btn.textContent = '⏳ Saving…';

    const status = document.getElementById('es-save-status');
    const txt = document.getElementById('es-save-text');
    status.className = 'es-save-status saving';
    txt.textContent = 'Saving…';

    // Build payload
    const payload = signItems.map(item => {
        const typeId = Array.isArray(item.type_id) ? item.type_id[0] : item.type_id;
        const roleId = Array.isArray(item.responsible_id) ? item.responsible_id[0] : (item.responsible_id || false);
        return {
            id: item.id > 0 ? item.id : 0,
            type_id: typeId,
            page: item.page,
            posX: item.posX,
            posY: item.posY,
            width: item.width,
            height: item.height,
            required: item.required,
            responsible_id: roleId || false,
            name: item.name || '',
            placeholder: item.placeholder || '',
            alignment: 'center',
        };
    });

    try {
        const response = await fetch('/sign/template/' + TEMPLATE_ID + '/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { items: payload } }),
        });
        const result = await response.json();
        if (result.result === true || result.result) {
            markSaved();
            showToast('✓ Template saved successfully!', 'success');
            // Reload to get real IDs for newly created items
            setTimeout(() => location.reload(), 1200);
        } else {
            throw new Error(result.error?.data?.message || 'Save failed');
        }
    } catch (err) {
        status.className = 'es-save-status error';
        txt.textContent = 'Save failed';
        showToast('✗ ' + (err.message || 'Failed to save'), 'error');
    } finally {
        btn.disabled = false;
        btn.innerHTML = '&#10003; Save Template';
    }
}

window.saveTemplate = saveTemplate;

/* ========================================================
   DISCARD
   ======================================================== */
function discardChanges() {
    if (isDirty) {
        if (!confirm('Discard all unsaved changes?')) return;
    }
    location.reload();
}
window.discardChanges = discardChanges;

/* ========================================================
   TOAST
   ======================================================== */
function showToast(msg, type = 'success') {
    const toast = document.getElementById('es-toast');
    toast.textContent = msg;
    toast.className = `es-toast ${type} show`;
    setTimeout(() => { toast.classList.remove('show'); }, 3000);
}

/* ========================================================
   BOOT
   ======================================================== */
// Populate sign items from server
function parseSignItems(raw) {
    return raw.map(it => ({
        _id: it.id, // real DB id as _id for existing items
        id: it.id,
        type_id: it.type_id,
        type: it.type_id ? it.type_id[1] : 'text', // [id, item_type] pair? Let's resolve below
        page: it.page,
        posX: it.posX,
        posY: it.posY,
        width: it.width,
        height: it.height,
        required: it.required,
        responsible_id: it.responsible_id,
        name: it.name || '',
        placeholder: it.placeholder || '',
    }));
}

// Resolve item_type string from type_id
function resolveItemType(item) {
    if (!item.type_id) return 'text';
    const typeIdNum = Array.isArray(item.type_id) ? item.type_id[0] : item.type_id;
    const found = SIGN_ITEM_TYPES.find(t => t.id === typeIdNum);
    return found ? found.item_type : 'text';
}

// Initialize
signItems = INITIAL_ITEMS.map(it => {
    const obj = {
        _id: it.id,
        id: it.id,
        type_id: it.type_id,
        type: resolveItemType(it),
        page: it.page,
        posX: it.posX,
        posY: it.posY,
        width: it.width,
        height: it.height,
        required: it.required,
        responsible_id: it.responsible_id,
        name: it.name || '',
        placeholder: it.placeholder || '',
    };
    return obj;
});


// Mark as saved initially (no unsaved changes)
const statusEl = document.getElementById('es-save-status');
const statusTxt = document.getElementById('es-save-text');
statusEl.className = 'es-save-status saved';
statusTxt.textContent = 'No unsaved changes';

// Pre-fill send reference
const refInput = document.getElementById('es-send-reference');
if (refInput) refInput.value = TEMPLATE_NAME;

/* ========================================================
   SIGNERS PANEL — dynamic multi-signer list
   ======================================================== */
let signerRowCount = 0;

// Color palette for signers
const SIGNER_COLORS = [
    '#6366f1','#10b981','#f59e0b','#ef4444','#3b82f6',
    '#8b5cf6','#ec4899','#14b8a6','#f97316','#84cc16'
];

function getSignerColor(idx) {
    return SIGNER_COLORS[(idx - 1) % SIGNER_COLORS.length];
}

function buildRoleOptions(selectedRoleId) {
    let html = '<option value="">— No role —</option>';
    SIGN_ROLES.forEach(function(role) {
        const sel = (role.id === selectedRoleId) ? ' selected="selected"' : '';
        html += '<option value="' + role.id + '"' + sel + '>' + role.name + '</option>';
    });
    return html;
}

const ALL_FIELD_TYPES = [
    { typeId: 1, itemType: 'signature', name: 'Signature', label: 'Signature', icon: '✍' },
    { typeId: 2, itemType: 'initial',   name: 'Initials',  label: 'Initials',  icon: '📝' },
    { typeId: 3, itemType: 'text',      name: 'Name',      label: 'Name',      icon: '👤', defName: 'Name', defPlaceholder: 'Name' },
    { typeId: 3, itemType: 'text',      name: 'Email',     label: 'Email',     icon: '✉', defName: 'Email', defPlaceholder: 'Email' },
    { typeId: 3, itemType: 'text',      name: 'Phone',     label: 'Phone',     icon: '📞', defName: 'Phone', defPlaceholder: 'Phone' },
    { typeId: 3, itemType: 'text',      name: 'Company',   label: 'Company',   icon: '🏢', defName: 'Company', defPlaceholder: 'Company' },
    { typeId: 3, itemType: 'text',      name: 'Text',      label: 'Text',      icon: 'A' },
    { typeId: 4, itemType: 'textarea',  name: 'Multiline', label: 'Multiline', icon: '≡' },
    { typeId: 5, itemType: 'checkbox',  name: 'Checkbox',  label: 'Checkbox',  icon: '☑' },
    { typeId: 5, itemType: 'checkbox',  name: 'Radio',     label: 'Radio',     icon: '⚪', defName: 'Radio' },
    { typeId: 3, itemType: 'text',      name: 'Selection', label: 'Selection', icon: '▼', defName: 'Selection' },
    { typeId: 3, itemType: 'text',      name: 'Date',      label: 'Date',      icon: '📅', defName: 'Date', defPlaceholder: 'Date' },
    { typeId: 3, itemType: 'text',      name: 'Strikethrough', label: 'Strikethrough', icon: '̶S', defName: 'Strikethrough' },
    { typeId: 1, itemType: 'signature', name: 'Stamp',     label: 'Stamp',     icon: '🖼', defName: 'Stamp' }
];

function buildSignerFieldCards(signerIdx, color) {
    let html = '<div class="es-signer-fields" id="signer-fields-' + signerIdx + '">';
    ALL_FIELD_TYPES.forEach(function(t) {
        html += '<div class="es-signer-field-card"' +
            ' draggable="true"' +
            ' data-type-id="' + t.typeId + '"' +
            ' data-item-type="' + t.itemType + '"' +
            ' data-type-name="' + t.name + '"' +
            ' data-signer-idx="' + signerIdx + '"' +
            ' data-signer-color="' + color + '"' +
            (t.defName ? ' data-def-name="' + t.defName + '"' : '') +
            (t.defPlaceholder ? ' data-def-placeholder="' + t.defPlaceholder + '"' : '') +
            ' style="background:' + color + '18; border-color:' + color + '33; color:' + color + ';"' +
            ' title="Drag to place ' + t.label + ' for Signer ' + signerIdx + '">' +
            '<span class="es-sfc-icon">' + t.icon + '</span>' +
            '<span class="es-sfc-label">' + t.label + '</span>' +
        '</div>';
    });
    html += '<button class="es-signer-field-add-btn" style="grid-column: span 2; background:' + color + '10; border: 1px dashed ' + color + '44; color:' + color + ';" onclick="event.preventDefault();">+ Add Field</button>';
    html += '</div>';
    return html;
}

function getNextUnusedRoleId() {
    const list = document.getElementById('es-signers-list');
    if (!list) return '';
    const usedRoleIds = [];
    list.querySelectorAll('.es-signer-row').forEach(row => {
        const idx = row.id.replace('signer-row-', '');
        const roleEl = document.getElementById('signer-role-' + idx);
        if (roleEl && roleEl.value) {
            usedRoleIds.push(parseInt(roleEl.value, 10));
        }
    });
    const unusedRole = SIGN_ROLES.find(r => !usedRoleIds.includes(r.id));
    return unusedRole ? unusedRole.id : (SIGN_ROLES[0] ? SIGN_ROLES[0].id : '');
}

function buildSignersPanel() {
    // Group existing items by role_id to identify signers needed
    const rolesUsed = [];
    signItems.forEach(item => {
        const roleId = Array.isArray(item.responsible_id) ? item.responsible_id[0] : item.responsible_id;
        if (roleId && !rolesUsed.includes(roleId)) {
            rolesUsed.push(roleId);
        }
    });

    if (rolesUsed.length === 0) {
        addSignerRow();
    } else {
        rolesUsed.forEach(roleId => {
            addSignerRow({ role_id: roleId });
        });

        // Associate items with signer rows
        signItems.forEach(item => {
            const roleId = Array.isArray(item.responsible_id) ? item.responsible_id[0] : item.responsible_id;
            if (roleId) {
                const list = document.getElementById('es-signers-list');
                const rows = list ? list.querySelectorAll('.es-signer-row') : [];
                let foundIdx = null;
                rows.forEach(row => {
                    const idx = parseInt(row.id.replace('signer-row-', ''), 10);
                    const roleEl = document.getElementById('signer-role-' + idx);
                    if (roleEl && parseInt(roleEl.value, 10) === roleId) {
                        foundIdx = idx;
                    }
                });
                if (foundIdx !== null) {
                    item._signerIdx = foundIdx;
                    item._signerColor = getSignerColor(foundIdx);
                }
            }
        });
        updateSignerFieldCounts();
    }
}

function updateSignerFieldCounts() {
    const list = document.getElementById('es-signers-list');
    if (!list) return;
    const rows = list.querySelectorAll('.es-signer-row');
    rows.forEach(row => {
        const idx = parseInt(row.id.replace('signer-row-', ''), 10);
        const count = signItems.filter(item => item._signerIdx === idx).length;
        const badge = row.querySelector('.es-signer-badge');
        if (badge) badge.textContent = count;
    });
}

function addSignerRow(data) {
    signerRowCount++;
    const hint = document.getElementById('es-no-signers-hint');
    if (hint) hint.style.display = 'none';

    const list = document.getElementById('es-signers-list');
    const idx   = signerRowCount;
    const color = getSignerColor(idx);
    const row   = document.createElement('div');
    row.className = 'es-signer-row';
    row.id = 'signer-row-' + idx;
    row.style.borderColor = color + '44';

    const nameVal  = (data && data.name)  ? data.name  : '';
    const emailVal = (data && data.email) ? data.email : '';
    const roleVal  = (data && data.role_id) ? data.role_id : getNextUnusedRoleId();

    row.innerHTML =
        '<div class="es-signer-row-header" style="display:flex; align-items:center; justify-content:space-between; width:100%;">' +
            '<span class="es-signer-num" style="color:' + color + '; font-weight:600; font-size:13px; display:inline-flex; align-items:center;">' +
                '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + color + ';margin-right:5px;"></span>' +
                'Signer ' + idx +
            '</span>' +
            '<div style="display:flex; align-items:center; gap:6px;">' +
                '<span class="es-signer-badge" style="font-size:10px; font-weight:700; min-width:18px; height:18px; display:inline-flex; align-items:center; justify-content:center; border-radius:50%; padding:0 4px; background:' + color + '22; color:' + color + '; border:1px solid ' + color + '44;">0</span>' +
                '<button class="es-signer-menu-btn" title="Signer Actions" style="background:transparent; border:none; color:#64748b; cursor:pointer; font-size:14px; line-height:1; padding:2px 4px; border-radius:4px;">&#8942;</button>' +
                '<button class="es-signer-remove" title="Remove signer" style="width:18px; height:18px; display:flex; align-items:center; justify-content:center; border-radius:4px; border:none; background:rgba(239,68,68,0.1); color:#f87171; font-size:12px; cursor:pointer; line-height:1; padding:0;"' +
                    ' onclick="removeSignerRow(' + idx + ')">&#215;</button>' +
            '</div>' +
        '</div>' +
        '<div class="es-signer-inputs" style="display:flex; flex-direction:column; gap:4px; margin-top:4px; margin-bottom:4px;">' +
            '<input class="es-signer-input" type="text"' +
                ' id="signer-name-' + idx + '"' +
                ' placeholder="Full name..."' +
                ' value="' + nameVal.replace(/"/g, '&quot;') + '"' +
                ' autocomplete="off"/>' +
            '<input class="es-signer-input" type="email"' +
                ' id="signer-email-' + idx + '"' +
                ' placeholder="Email address..."' +
                ' value="' + emailVal.replace(/"/g, '&quot;') + '"' +
                ' autocomplete="off"/>' +
            (SIGN_ROLES.length > 0
                ? '<select class="es-signer-select" id="signer-role-' + idx + '">' +
                      buildRoleOptions(roleVal ? parseInt(roleVal, 10) : null) +
                  '</select>'
                : '') +
        '</div>' +
        buildSignerFieldCards(idx, color);

    list.appendChild(row);
    updateSignerCount();
    updateSignerFieldCounts();

    // Attach drag events to this signer's field cards
    const fieldCards = row.querySelectorAll('.es-signer-field-card');
    fieldCards.forEach(function(card) {
        card.addEventListener('dragstart', onSidebarDragStart);
        card.addEventListener('dragend', function() { card.classList.remove('dragging'); });
    });

    const nameEl = document.getElementById('signer-name-' + idx);
    const emailEl = document.getElementById('signer-email-' + idx);
    const roleEl = document.getElementById('signer-role-' + idx);

    const onSignerInfoChange = () => {
        if (selectedItemId !== null) {
            const selectedItem = signItems.find(it => it._id === selectedItemId);
            if (selectedItem) {
                updatePropSignerSelect(selectedItem._signerIdx);
            }
        }
    };

    if (nameEl) nameEl.addEventListener('input', onSignerInfoChange);
    if (emailEl) emailEl.addEventListener('input', onSignerInfoChange);
    if (roleEl) {
        roleEl.addEventListener('change', function() {
            const newRoleId = roleEl.value ? parseInt(roleEl.value, 10) : false;
            signItems.forEach(item => {
                if (item._signerIdx === idx) {
                    item.responsible_id = newRoleId;
                    const el = document.getElementById(`sfi-${item._id}`);
                    if (el) {
                        applyRoleColorToEl(el, newRoleId, color);
                    }
                }
            });
            onSignerInfoChange();
            markDirty();
        });
    }

    const nameInput = document.getElementById('signer-name-' + idx);
    if (nameInput) setTimeout(function() { nameInput.focus(); }, 50);
}
window.addSignerRow = addSignerRow;

function removeSignerRow(idx) {
    const row = document.getElementById('signer-row-' + idx);
    if (row) row.remove();

    // Clear signer assignment for all fields assigned to this signer
    signItems.forEach(item => {
        if (item._signerIdx === idx) {
            item._signerIdx = null;
            item._signerColor = null;
            item.responsible_id = false;

            const el = document.getElementById(`sfi-${item._id}`);
            if (el) {
                applyRoleColorToEl(el, false, null);
            }
        }
    });

    if (selectedItemId !== null) {
        const selectedItem = signItems.find(it => it._id === selectedItemId);
        if (selectedItem) {
            showPropsPanel(selectedItem);
        }
    }

    updateSignerCount();
    const list = document.getElementById('es-signers-list');
    const remaining = list ? list.querySelectorAll('.es-signer-row') : [];
    if (remaining.length === 0) {
        const hint = document.getElementById('es-no-signers-hint');
        if (hint) hint.style.display = '';
    }
    markDirty();
    updateSignerFieldCounts();
}
window.removeSignerRow = removeSignerRow;

function updateSignerCount() {
    const list  = document.getElementById('es-signers-list');
    const count = list ? list.querySelectorAll('.es-signer-row').length : 0;
    const badge = document.getElementById('es-signers-count');
    if (badge) badge.textContent = count;
}

/* ========================================================
   COLLECT SIGNERS FROM PANEL
   ======================================================== */
function collectSigners() {
    const signers = [];
    const list = document.getElementById('es-signers-list');
    if (!list) return signers;
    const rows = list.querySelectorAll('.es-signer-row');
    rows.forEach(function(row) {
        const idx   = row.id.replace('signer-row-', '');
        const nameEl  = document.getElementById('signer-name-'  + idx);
        const emailEl = document.getElementById('signer-email-' + idx);
        const roleEl  = document.getElementById('signer-role-'  + idx);
        const name  = nameEl  ? nameEl.value.trim()  : '';
        const email = emailEl ? emailEl.value.trim() : '';
        const roleId = (roleEl && roleEl.value) ? parseInt(roleEl.value, 10) : null;
        if (email) {
            signers.push({ role_id: roleId, name: name || email, email: email });
        }
    });
    return signers;
}

/* ========================================================
   OPEN / CLOSE SEND MODAL
   ======================================================== */
function openSendModal() {
    const signers = collectSigners();
    const preview = document.getElementById('es-modal-signer-preview');
    if (preview) {
        if (signers.length === 0) {
            preview.innerHTML =
                '<div style="font-size:12px;color:#f87171;">' +
                    '&#9888; No signer emails entered. Fill in emails in the Signers section.' +
                '</div>';
        } else {
            preview.innerHTML = signers.map(function(s) {
                return '<div class="es-modal-signer-item">' +
                    '<span>&#9993;</span>' +
                    '<strong>' + (s.name || s.email) + '</strong>' +
                    '<span style="color:#475569;">&lt;' + s.email + '&gt;</span>' +
                '</div>';
            }).join('');
        }
    }
    const modal = document.getElementById('es-send-modal');
    if (modal) modal.classList.add('open');
}
window.openSendModal = openSendModal;

function closeSendModal() {
    const modal = document.getElementById('es-send-modal');
    if (modal) modal.classList.remove('open');
}
window.closeSendModal = closeSendModal;

// Close modal on backdrop click
document.getElementById('es-send-modal').addEventListener('click', function(e) {
    if (e.target === this) closeSendModal();
});

/* ========================================================
   CONFIRM SEND
   ======================================================== */
async function confirmSend() {
    const signers   = collectSigners();
    const reference = (document.getElementById('es-send-reference').value || '').trim();
    const subject   = (document.getElementById('es-send-subject').value   || '').trim();

    if (signers.length === 0) {
        showToast('Please enter at least one signer email in the Signers section.', 'error');
        closeSendModal();
        return;
    }

    const btn = document.getElementById('es-send-confirm-btn');
    btn.disabled = true;
    btn.textContent = 'Sending\u2026';

    try {
        const resp = await fetch(
            '/sign/template/' + TEMPLATE_ID + '/send',
            {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0', method: 'call',
                    params: { signers: signers, reference: reference, subject: subject }
                })
            }
        );
        const data = await resp.json();
        const result = data.result;

        if (result && result.success) {
            showToast('Signature request sent!', 'success');
            closeSendModal();
            setTimeout(function() {
                window.location.href = '/odoo/sign-requests/' + result.request_id;
            }, 1200);
        } else {
            const msg = (result && result.error) || 'Failed to send request';
            showToast(msg, 'error');
        }
    } catch (err) {
        showToast('Network error: ' + (err.message || 'Unknown'), 'error');
    } finally {
        btn.disabled = false;
        btn.innerHTML = '&#9993; Send Now';
    }
}
window.confirmSend = confirmSend;

isEditMode = (signItems.length === 0);
buildSignersPanel();
renderPDF('/sign/template/' + TEMPLATE_ID + '/pdf');

})();
